        if self.NATIVE_TIME_SYSTEM is not None:
            NCDAddNATIVE_TIME_SYSTEM(builder, NATIVE_TIME_SYSTEM)
        if self.SEGMENTS is not None:
            NCDAddSEGMENTS(builder, SEGMENTS)
        if self.SP3_HEADER is not None:
            NCDAddSP3_HEADER(builder, SP3_HEADER)
        if self.SCENARIO_CONTAINER is not None:
            NCDAddSCENARIO_CONTAINER(builder, SCENARIO_CONTAINER)
        if self.CODE_500_HEADER is not None:
            NCDAddCODE_500_HEADER(builder, CODE_500_HEADER)
        if self.START_TIME is not None:
            NCDAddSTART_TIME(builder, START_TIME)
        if self.STOP_TIME is not None:
            NCDAddSTOP_TIME(builder, STOP_TIME)
        NCDAddSOURCE_BYTE_LENGTH(builder, self.SOURCE_BYTE_LENGTH)
        if self.SOURCE_SHA256 is not None:
            NCDAddSOURCE_SHA256(builder, SOURCE_SHA256)
        if self.SOURCE_CID is not None:
            NCDAddSOURCE_CID(builder, SOURCE_CID)
        NCD = NCDEnd(builder)
        return NCD
